using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextHelper
    {
        public static SchoolContext CreateContext(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        public static SchoolContext CreateSeededContext(string? dbName = null)
        {
            var context = CreateContext(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            var instructor1 = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = DateTime.Parse("1995-03-11")
            };
            var instructor2 = new Instructor
            {
                FirstMidName = "Fadi",
                LastName = "Fakhouri",
                HireDate = DateTime.Parse("2002-07-06")
            };

            context.Instructors.AddRange(instructor1, instructor2);
            context.SaveChanges();

            var department1 = new Department
            {
                Name = "English",
                Budget = 350000,
                StartDate = DateTime.Parse("2007-09-01"),
                InstructorID = instructor1.ID
            };
            var department2 = new Department
            {
                Name = "Mathematics",
                Budget = 100000,
                StartDate = DateTime.Parse("2007-09-01"),
                InstructorID = instructor2.ID
            };

            context.Departments.AddRange(department1, department2);
            context.SaveChanges();

            var course1 = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = department1.DepartmentID
            };
            var course2 = new Course
            {
                CourseID = 4022,
                Title = "Microeconomics",
                Credits = 3,
                DepartmentID = department2.DepartmentID
            };

            context.Courses.AddRange(course1, course2);
            context.SaveChanges();

            var student1 = new Student
            {
                FirstMidName = "Carson",
                LastName = "Alexander",
                EnrollmentDate = DateTime.Parse("2010-09-01")
            };
            var student2 = new Student
            {
                FirstMidName = "Meredith",
                LastName = "Alonso",
                EnrollmentDate = DateTime.Parse("2012-09-01")
            };
            var student3 = new Student
            {
                FirstMidName = "Arturo",
                LastName = "Anand",
                EnrollmentDate = DateTime.Parse("2013-09-01")
            };

            context.Students.AddRange(student1, student2, student3);
            context.SaveChanges();

            context.Enrollments.Add(new Enrollment
            {
                StudentID = student1.ID,
                CourseID = course1.CourseID,
                Grade = Grade.A
            });
            context.SaveChanges();

            // Add office assignments
            context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = instructor2.ID,
                Location = "Smith 17"
            });
            context.SaveChanges();

            // Add course assignments
            context.CourseAssignments.Add(new CourseAssignment
            {
                CourseID = course1.CourseID,
                InstructorID = instructor1.ID
            });
            context.SaveChanges();
        }
    }
}

using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Fact]
        public void FullName_ReturnsLastNameCommaFirstName()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "Carson",
                LastName = "Alexander"
            };

            // Act
            var result = student.FullName;

            // Assert
            Assert.Equal("Alexander, Carson", result);
        }

        [Fact]
        public void FullName_WithDifferentNames_ReturnsCorrectFormat()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie"
            };

            // Act
            var result = instructor.FullName;

            // Assert
            Assert.Equal("Abercrombie, Kim", result);
        }

        [Fact]
        public void ID_DefaultValue_IsZero()
        {
            var student = new Student();
            Assert.Equal(0, student.ID);
        }
    }
}

using ContosoUniversity.Models;
using System;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class StudentTests
    {
        [Fact]
        public void EnrollmentDate_CanBeSet()
        {
            var date = new DateTime(2023, 9, 1);
            var student = new Student { EnrollmentDate = date };
            Assert.Equal(date, student.EnrollmentDate);
        }

        [Fact]
        public void Enrollments_CanBeInitializedEmpty()
        {
            var student = new Student
            {
                Enrollments = new System.Collections.Generic.List<Enrollment>()
            };
            Assert.Empty(student.Enrollments);
        }

        [Fact]
        public void Student_InheritsFromPerson()
        {
            var student = new Student
            {
                FirstMidName = "John",
                LastName = "Doe",
                EnrollmentDate = DateTime.Today
            };
            Assert.IsAssignableFrom<Person>(student);
            Assert.Equal("Doe, John", student.FullName);
        }
    }
}

using ContosoUniversity.Models;
using System;
using System.Collections.Generic;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class InstructorTests
    {
        [Fact]
        public void HireDate_CanBeSet()
        {
            var date = new DateTime(2000, 1, 15);
            var instructor = new Instructor { HireDate = date };
            Assert.Equal(date, instructor.HireDate);
        }

        [Fact]
        public void Instructor_InheritsFromPerson()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = DateTime.Today
            };
            Assert.IsAssignableFrom<Person>(instructor);
            Assert.Equal("Abercrombie, Kim", instructor.FullName);
        }

        [Fact]
        public void CourseAssignments_CanBePopulated()
        {
            var instructor = new Instructor
            {
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = 1, InstructorID = 1 }
                }
            };
            Assert.Single(instructor.CourseAssignments);
        }

        [Fact]
        public void OfficeAssignment_CanBeSet()
        {
            var instructor = new Instructor
            {
                OfficeAssignment = new OfficeAssignment { Location = "Smith 17" }
            };
            Assert.Equal("Smith 17", instructor.OfficeAssignment.Location);
        }
    }
}

