+using System.Collections.Generic;
+using System.Linq;
+using Xunit;
+
+namespace ContosoUniversity.Tests
+{
+    public class PaginatedListTests
+    {
+        [Fact]
+        public void Constructor_SetsPageIndexAndTotalPages()
+        {
+            var items = new List<string> { "a", "b", "c" };
+
+            var list = new PaginatedList<string>(items, 10, 2, 3);
+
+            Assert.Equal(2, list.PageIndex);
+            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
+            Assert.Equal(3, list.Count);
+        }
+
+        [Fact]
+        public void Constructor_ContainsAllItems()
+        {
+            var items = new List<int> { 1, 2, 3 };
+
+            var list = new PaginatedList<int>(items, 5, 1, 3);
+
+            Assert.Contains(1, list);
+            Assert.Contains(2, list);
+            Assert.Contains(3, list);
+        }
+
+        [Fact]
+        public void HasPreviousPage_OnFirstPage_ReturnsFalse()
+        {
+            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);
+            Assert.False(list.HasPreviousPage);
+        }
+
+        [Fact]
+        public void HasPreviousPage_OnSecondPage_ReturnsTrue()
+        {
+            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);
+            Assert.True(list.HasPreviousPage);
+        }
+
+        [Fact]
+        public void HasNextPage_OnLastPage_ReturnsFalse()
+        {
+            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);
+            Assert.False(list.HasNextPage);
+        }
+
+        [Fact]
+        public void HasNextPage_OnFirstPage_WhenMorePagesExist_ReturnsTrue()
+        {
+            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);
+            Assert.True(list.HasNextPage);
+        }
+
+        [Fact]
+        public void TotalPages_CalculatedCorrectly_WithExactDivision()
+        {
+            var list = new PaginatedList<int>(new List<int>(), 10, 1, 5);
+            Assert.Equal(2, list.TotalPages);
+        }
+
+        [Fact]
+        public void TotalPages_CalculatedCorrectly_WithRemainder()
+        {
+            var list = new PaginatedList<int>(new List<int>(), 11, 1, 5);
+            Assert.Equal(3, list.TotalPages);
+        }
+
+        [Fact]
+        public void TotalPages_WithSingleItem_IsOne()
+        {
+            var list = new PaginatedList<int>(new List<int> { 1 }, 1, 1, 10);
+            Assert.Equal(1, list.TotalPages);
+        }
+
+        [Fact]
+        public void Create_ReturnsCorrectPage()
+        {
+            var source = Enumerable.Range(1, 20).AsQueryable();
+
+            var result = PaginatedList<int>.Create(source, 2, 5);
+
+            Assert.Equal(2, result.PageIndex);
+            Assert.Equal(4, result.TotalPages);
+            Assert.Equal(5, result.Count);
+            Assert.Equal(6, result[0]);
+            Assert.Equal(10, result[4]);
+        }
+
+        [Fact]
+        public void Create_FirstPage_ContainsFirstItems()
+        {
+            var source = Enumerable.Range(1, 15).AsQueryable();
+
+            var result = PaginatedList<int>.Create(source, 1, 5);
+
+            Assert.Equal(1, result.PageIndex);
+            Assert.Equal(3, result.TotalPages);
+            Assert.Equal(5, result.Count);
+            Assert.Equal(1, result[0]);
+            Assert.Equal(5, result[4]);
+        }
+
+        [Fact]
+        public void Create_LastPage_ContainsRemainingItems()
+        {
+            var source = Enumerable.Range(1, 13).AsQueryable();
+
+            var result = PaginatedList<int>.Create(source, 3, 5);
+
+            Assert.Equal(3, result.PageIndex);
+            Assert.Equal(3, result.TotalPages);
+            Assert.Equal(3, result.Count);
+            Assert.Equal(11, result[0]);
+            Assert.Equal(13, result[2]);
+        }
+
+        [Fact]
+        public void HasPreviousPage_And_HasNextPage_OnMiddlePage_BothTrue()
+        {
+            var source = Enumerable.Range(1, 30).AsQueryable();
+            var result = PaginatedList<int>.Create(source, 2, 10);
+
+            Assert.True(result.HasPreviousPage);
+            Assert.True(result.HasNextPage);
+        }
+    }
+}
