1. using ContosoUniversity.Models;
2. using ContosoUniversity.Services;
3. using System;
4. using Xunit;
5. 
6. namespace ContosoUniversity.Tests.Services
7. {
8.     public class NotificationServiceTests : IDisposable
9.     {
10.         private readonly NotificationService _service;
11. 
12.         public NotificationServiceTests()
13.         {
14.             _service = new NotificationService();
15.             // Drain any existing notifications from the static queue
16.             while (_service.ReceiveNotification() != null) { }
17.         }
18. 
19.         [Fact]
20.         public void SendNotification_WithDisplayName_EnqueuesNotification()
21.         {
22.             // Act
23.             _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");
24. 
25.             // Assert
26.             var notification = _service.ReceiveNotification();
27.             Assert.NotNull(notification);
28.             Assert.Equal("Student", notification.EntityType);
29.             Assert.Equal("1", notification.EntityId);
30.             Assert.Equal("CREATE", notification.Operation);
31.             Assert.Contains("John Doe", notification.Message);
32.             Assert.Contains("created", notification.Message);
33.             Assert.Equal("admin", notification.CreatedBy);
34.             Assert.False(notification.IsRead);
35.         }
36. 
37.         [Fact]
38.         public void SendNotification_WithoutDisplayName_UsesEntityId()
39.         {
40.             // Act
41.             _service.SendNotification("Course", "42", null, EntityOperation.UPDATE, "user1");
42. 
43.             // Assert
44.             var notification = _service.ReceiveNotification();
45.             Assert.NotNull(notification);
46.             Assert.Contains("ID: 42", notification.Message);
47.             Assert.Contains("updated", notification.Message);
48.         }
49. 
50.         [Fact]
51.         public void SendNotification_WithoutUserName_DefaultsToSystem()
52.         {
53.             // Act
54.             _service.SendNotification("Student", "1", EntityOperation.CREATE);
55. 
56.             // Assert
57.             var notification = _service.ReceiveNotification();
58.             Assert.NotNull(notification);
59.             Assert.Equal("System", notification.CreatedBy);
60.         }
61. 
62.         [Fact]
63.         public void SendNotification_CreateOperation_GeneratesCorrectMessage()
64.         {
65.             _service.SendNotification("Student", "1", "Jane Smith", EntityOperation.CREATE);
66. 
67.             var notification = _service.ReceiveNotification();
68.             Assert.NotNull(notification);
69.             Assert.Equal("New Student 'Jane Smith' has been created", notification.Message);
70.         }
71. 
72.         [Fact]
73.         public void SendNotification_UpdateOperation_GeneratesCorrectMessage()
74.         {
75.             _service.SendNotification("Course", "100", "Math 101", EntityOperation.UPDATE);
76. 
77.             var notification = _service.ReceiveNotification();
78.             Assert.NotNull(notification);
79.             Assert.Equal("Course 'Math 101' has been updated", notification.Message);
80.         }
81. 
82.         [Fact]
83.         public void SendNotification_DeleteOperation_GeneratesCorrectMessage()
84.         {
85.             _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE);
86. 
87.             var notification = _service.ReceiveNotification();
88.             Assert.NotNull(notification);
89.             Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
90.         }
91. 
92.         [Fact]
93.         public void SendNotification_WithoutDisplayName_GeneratesMessageWithId()
94.         {
95.             _service.SendNotification("Student", "99", null, EntityOperation.CREATE);
96. 
97.             var notification = _service.ReceiveNotification();
98.             Assert.NotNull(notification);
99.             Assert.Equal("New Student (ID: 99) has been created", notification.Message);
100.         }
101. 
102.         [Fact]
103.         public void SendNotification_EmptyDisplayName_GeneratesMessageWithId()
104.         {
105.             _service.SendNotification("Student", "99", "  ", EntityOperation.CREATE);
106. 
107.             var notification = _service.ReceiveNotification();
108.             Assert.NotNull(notification);
109.             Assert.Contains("ID: 99", notification.Message);
110.         }
111. 
112.         [Fact]
113.         public void ReceiveNotification_WhenQueueEmpty_ReturnsNull()
114.         {
115.             var result = _service.ReceiveNotification();
116.             Assert.Null(result);
117.         }
118. 
119.         [Fact]
120.         public void ReceiveNotification_ReturnsInFifoOrder()
121.         {
122.             _service.SendNotification("Student", "1", "First", EntityOperation.CREATE);
123.             _service.SendNotification("Student", "2", "Second", EntityOperation.UPDATE);
124. 
125.             var first = _service.ReceiveNotification();
126.             var second = _service.ReceiveNotification();
127. 
128.             Assert.NotNull(first);
129.             Assert.NotNull(second);
130.             Assert.Contains("First", first.Message);
131.             Assert.Contains("Second", second.Message);
132.         }
133. 
134.         [Fact]
135.         public void MarkAsRead_DoesNotThrow()
136.         {
137.             // MarkAsRead is a no-op for in-memory, just ensure it doesn't throw
138.             var exception = Record.Exception(() => _service.MarkAsRead(1));
139.             Assert.Null(exception);
140.         }
141. 
142.         [Fact]
143.         public void Dispose_DoesNotThrow()
144.         {
145.             var exception = Record.Exception(() => _service.Dispose());
146.             Assert.Null(exception);
147.         }
148. 
149.         [Fact]
150.         public void SendNotification_TwoParamOverload_EnqueuesNotification()
151.         {
152.             _service.SendNotification("Instructor", "10", EntityOperation.DELETE);
153. 
154.             var notification = _service.ReceiveNotification();
155.             Assert.NotNull(notification);
156.             Assert.Equal("Instructor", notification.EntityType);
157.             Assert.Equal("10", notification.EntityId);
158.             Assert.Equal("DELETE", notification.Operation);
159.             Assert.Contains("Instructor", notification.Message);
160.         }
161. 
162.         [Fact]
163.         public void SendNotification_SetsCreatedAtToRecentTime()
164.         {
165.             var before = DateTime.Now.AddSeconds(-1);
166.             _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
167.             var after = DateTime.Now.AddSeconds(1);
168. 
169.             var notification = _service.ReceiveNotification();
170.             Assert.NotNull(notification);
171.             Assert.InRange(notification.CreatedAt, before, after);
172.         }
173. 
174.         public void Dispose()
175.         {
176.             // Drain the static queue to avoid polluting other tests
177.             while (_service.ReceiveNotification() != null) { }
178.             _service.Dispose();
179.         }
180.     }
181. }
