    [Fact]
    public void HasPreviousPage_And_HasNextPage_OnMiddlePage_BothTrue()
    {
        var source = Enumerable.Range(1, 30).AsQueryable();
        var result = PaginatedList<int>.Create(source, 2, 10);

        Assert.True(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void HasPreviousPage_PageIndex1_IsFalse_NotLessOrEqual()
    {
        // If mutated to >= instead of >, PageIndex=1 would return true
        var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);
        Assert.False(list.HasPreviousPage);
        // Explicitly verify page 2 DOES have previous
        var list2 = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);
        Assert.True(list2.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_OnExactLastPage_IsFalse()
    {
        // TotalPages = ceil(10/5) = 2, PageIndex = 2 → no next page
        var list = new PaginatedList<int>(new List<int>(), 10, 2, 5);
        Assert.False(list.HasNextPage);
        // But PageIndex = 1 → has next page
        var list2 = new PaginatedList<int>(new List<int>(), 10, 1, 5);
        Assert.True(list2.HasNextPage);
    }

    [Fact]
    public void TotalPages_WithRemainder_UsesCeiling_NotFloor()
    {
        // 11 items / 5 per page: floor = 2, ceiling = 3
        var list = new PaginatedList<int>(new List<int>(), 11, 1, 5);
        Assert.Equal(3, list.TotalPages);
        Assert.NotEqual(2, list.TotalPages); // Would be 2 with Floor
    }

    [Fact]
    public void Create_Page2_SkipsCorrectNumberOfItems()
    {
        // 10 items, page 2 with pageSize 3 should skip 3 items (index 0-2), take items 4-6
        var source = Enumerable.Range(1, 10).AsQueryable();
        var result = PaginatedList<int>.Create(source, 2, 3);

        Assert.Equal(3, result.Count);
        Assert.Equal(4, result[0]); // (2-1)*3 = Skip(3), Take(3) → 4,5,6
        Assert.Equal(5, result[1]);
        Assert.Equal(6, result[2]);
    }
}

