        [Fact]
        public void Create_Post_WithOutOfRangeEnrollmentDate_ReturnsViewWithError()
        {
            var student = new Student
            {
                FirstMidName = "Bad",
                LastName = "Date",
                EnrollmentDate = new DateTime(1752, 1, 1)
            };

            var result = _controller.Create(student);

